\section*{উদাহরণ-9.6: বায়ুর সাপেক্ষে কাচের প্রতিসরণাঙ্ক 1.5 | বায়ুতে এক আলোক বছর $9.4 \times 10^{12}$ km | কাচে এক আলোক বছরের মান বের করো।}

বায়ু ও কাচে আলোর দুটি যথাক্রমে $c_a$ ও $c_g$ এবং এক বছরে $t$ সেকেন্ড হলে বায়ু ও কাচে আলোক বছর যথাক্রমে-

\begin{equation}
L_a = c_a \times t \text{ ও } L_g = c_g \times t
\end{equation}

আমরা জানি, বায়ুর সাপেক্ষে কাচের প্রতিসরণাঙ্ক,

\begin{equation}
a\mu_g = \frac{c_a}{c_g} = \frac{c_a \times t}{c_g \times t} = \frac{L_a}{L_g}
\end{equation}

\begin{equation}
\therefore L_g = \frac{L_a}{a\mu_g}
\end{equation}

\begin{equation}
= \frac{9.4 \times 10^{12} \text{ km}}{1.5}
\end{equation}

\begin{equation}
= 6.267 \times 10^{12} \text{ km}
\end{equation}

\section*{উদাহরণ-9.9: শূন্য মাধ্যম থেকে অভিলম্বের সাথে 30° কোণে আগত একটি আলোকরশ্মির 2 cm পূর্ব একটি কাচ তেল করতে কত সময় লাগবে? কাচের প্রতিসরণাঙ্ক 1.5।}

আমরা জানি,

\begin{equation}
\mu = \frac{\sin i}{\sin r}
\end{equation}

বা, $\sin r = \frac{\sin 30^\circ}{\mu} = \frac{0.5}{1.5} = \frac{1}{3}$

\begin{equation}
\therefore r = 19.47^\circ
\end{equation}

চিত্র হতে,

\begin{equation}
AC = \frac{AB}{\cos r} = \frac{l}{\cos r} = \frac{0.02 \text{ m}}{\cos 19.47^\circ} = 0.021213 \text{ m}
\end{equation}

আবার, AC দূরত্ব অতিক্রম করতে সময়-

\begin{equation}
t = \frac{AC}{c_g}
\end{equation}

\begin{equation}
= \frac{\mu \times AC}{c} \quad \left[ \mu = \frac{c}{c_g} \right]
\end{equation}

\begin{equation}
= \frac{1.5 \times 0.021213 \text{ m}}{3 \times 10^8 \text{ m.s}^{-1}}
\end{equation}

\begin{equation}
= 0.106 \times 10^{-9} \text{ s}
\end{equation}

\begin{equation}
= 0.106 \text{ ns}
\end{equation}

