\therefore \lambda = d \times \frac{\sin\theta_2}{n} = 2.36 \times 10^{-6} \text{ m} \times \frac{\sin(40^{\circ})}{2}
\end{equation}

\begin{equation}
= 7.59 \times 10^{-7} \text{ m}
\end{equation}

এখন, চরমের ক্ষেত্রে আমরা জানি,

\begin{equation}
dsin\theta_n = n\lambda
\end{equation}

\begin{equation}
n = 1 \text{ হলে, } \sin\theta_1 = \frac{\lambda}{d} = \frac{7.59 \times 10^{-7} \text{ m}}{2.36 \times 10^{-6} \text{ m}}
\end{equation}

\begin{equation}
\therefore \theta_1 = 18.76^{\circ}
\end{equation}

$n = 2 \text{ হলে,}$

\begin{equation}
\theta_2 = 40^{\circ} \text{ (প্রদত্ত)}
\end{equation}

সুতরাং পরম্পর দুটো চরমের কৌণিক ব্যবধান, $(\theta_2 - \theta_1) = (40 - 18.76) = 21.24^{\circ}$

অবমের ক্ষেত্রে, আমরা জানি,

\begin{equation}
dsin\theta' = (2n + 1) \frac{\lambda}{2}
\end{equation}

$n = 1 \text{ হলে, } \sin\theta_1' = \frac{3\lambda}{2d} = \frac{3 \times 7.59 \times 10^{-7} \text{ m}}{2 \times 2.36 \times 10^{-6} \text{ m}}$

