    \item একটি তরঙ্গের দুটি বিন্দুর দশা পার্থক্য $\pi/2$। বিন্দু দ্বয়ের পথ-পার্থক্য কত?
        \begin{enumerate}
            \item $\lambda$
            \item $\lambda/2$
            \item $\lambda/4$
            \item $2\lambda/3$
        \end{enumerate}
    \item দুটি সৌজা ও সমত্তরাল চির পরম্পর হতে $a$ দূরে অবস্থিত। একটি একবীণা আলো দ্বারা এদের আলোকিত করায় চির হতে $D$ দূরে অবস্থিত পদ্মা ডোরা সৃষ্টি হলো। প্রতিটি ডোরার প্রস্থ $x$; পরবর্তীতে $a$ ও $D$ উভয়টিকে দ্বিগুণ করা হলো। নতুন ডোরার প্রস্থ হবে-
        \begin{enumerate}
            \item $\frac{1}{2}x$
            \item $4x$
            \item $2x$
            \item $1x$
        \end{enumerate}
\end{enumerate}
